 void OutlineText(Text text,Color color){var outline=text.gameObject.AddComponent<Outline>();outline.effectColor=color;outline.effectDistance=new Vector2(1,-1);}
 void MakeRound(){var tex=new Texture2D(64,64,TextureFormat.RGBA32,false);tex.filterMode=FilterMode.Bilinear;for(int y=0;y<64;y++)for(int x=0;x<64;x++){float dx=Mathf.Max(12-x,Mathf.Max(0,x-51)),dy=Mathf.Max(12-y,Mathf.Max(0,y-51));tex.SetPixel(x,y,new Color(1,1,1,Mathf.Clamp01(12.5f-Mathf.Sqrt(dx*dx+dy*dy))));}tex.Apply();rounded=Sprite.Create(tex,new Rect(0,0,64,64),new Vector2(.5f,.5f),100,0,SpriteMeshType.FullRect,new Vector4(14,14,14,14));}
 RectTransform Rect(Transform parent,string name,Vector2 p,Vector2 size){var go=new GameObject(name,typeof(RectTransform));var r=go.GetComponent<RectTransform>();r.SetParent(parent,false);r.anchorMin=r.anchorMax=new Vector2(0,1);r.pivot=new Vector2(0,1);r.anchoredPosition=p;r.sizeDelta=size;return r;}
