 void Update(){var s=GameSession.I;if(!s||!screen)return;bool portrait=s.ending&&s.ending.PortraitActive;hudCard.SetActive(s.Playing&&!portrait);inventory.transform.parent.gameObject.SetActive(s.Playing&&!portrait);promptCard.SetActive(s.Playing&&!portrait);toastCard.SetActive(!string.IsNullOrEmpty(s.toast)&&!portrait);toast.text=s.toast;portraitUI.SetActive(portrait);if(portrait){shutter.interactable=s.ending.PhotoReady&&!s.ending.Capturing;portraitHint.text=!s.ending.PhotoReady?"朋友们正在过来，镜头已经为你准备好了。":s.ending.Capturing?"看这里——把这个清晨留住。":"点击快门或按空格 · 自动构图 · 三秒倒数";countdown.text=s.ending.Countdown>0?s.ending.Countdown.ToString():"";curtain.color=new Color(cream.r,cream.g,cream.b,s.ending.FadeAlpha);}
  if(s.Playing&&!portrait){var delta=s.Target()-s.player.transform.position;float angle=Vector3.SignedAngle(Quaternion.Euler(0,s.view.yaw,0)*Vector3.forward,delta,Vector3.up);string arrow=Mathf.Abs(angle)<20?"↑":angle>0?"→":"←";hud.text=GameSession.Tasks[(int)s.step];route.text=arrow+"  "+delta.magnitude.ToString("F0")+" m   /   J 手账   P 相册   Esc 暂停";inventory.text=(s.items.selected==1?"● ":"○ ")+"食物 "+s.items.food+"     "+(s.items.selected==2?"● ":"○ ")+"小球 · "+(s.items.ballOut?"待捡回":s.items.hasBall?"在口袋里":"尚未找到")+"\n1 / 2 切换道具   Q 使用";prompt.text=s.view.photography?"＋  摄影模式\n左键快门  ·  滚轮缩放  ·  右键退出":s.items.Prompt();foreach(var cat in s.cats)if(Vector3.Distance(cat.transform.position,s.player.transform.position)<8){prompt.text+="\n"+CatLabel(cat);break;}promptCard.SetActive(!string.IsNullOrEmpty(prompt.text));}
