 public static string CatLabel(CatBrain cat){if(cat.IsFriend)return GameSession.I.config.cats[(int)cat.id].name+"  ·  朋友";string text=GameSession.I.config.cats[(int)cat.id].name+"  ·  亲密 "+cat.trust.ToString("F0")+" / 20";if(cat.learning)text+="\n"+cat.learning.StageName+"  /  "+cat.learning.hint;return text;}
