 void Diary(Transform r){var s=GameSession.I;int row=0;for(int i=0;i<5;i++){bool written=!string.IsNullOrEmpty(s.notes[i]);string number=(i+1).ToString("00");var dot=Card(r,"故事序号",new Vector2(91,-153-row*70),new Vector2(39,35),written?sage:new Color(.88f,.88f,.81f));Label(dot,new Vector2(4,-4),new Vector2(31,28),15,number).alignment=TextAnchor.MiddleCenter;Label(r,new Vector2(149,-153-row*70),new Vector2(905,55),19,written?s.notes[i]:GameSession.Tasks[i]+"  ·  待记录");row++;}Line(r,new Vector2(92,-517),new Vector2(963,1),sage);Label(r,new Vector2(92,-533),new Vector2(940,30),16,s.step>=StoryStep.GatherCats?"最后一页：去树下读照料记录，再给三位朋友拍张合照。":"今天不用拼地图。记住眼前的小事，就能继续往前。");}
 void Album(Transform r){var s=GameSession.I;if(s.photos.album.Count==0){Paw(r,new Vector2(470,-231),110,sage);Heading(r,new Vector2(260,-365),new Vector2(690,45),29,"相册还空着，故事已经开始。");return;}var viewport=Rect(r,"相册视口",new Vector2(85,-146),new Vector2(982,404));viewport.gameObject.AddComponent<Image>().color=cream;viewport.gameObject.AddComponent<Mask>().showMaskGraphic=false;var scroll=viewport.gameObject.AddComponent<ScrollRect>();var content=Rect(viewport,"本局实拍",Vector2.zero,new Vector2(970,Mathf.Max(404,Mathf.Ceil(s.photos.album.Count/3f)*263)));scroll.content=content;scroll.viewport=viewport;scroll.horizontal=false;scroll.movementType=ScrollRect.MovementType.Clamped;for(int i=0;i<s.photos.album.Count;i++){int index=i;var photo=s.photos.album[i];var pos=new Vector2(i%3*326,-i/3*263);var mount=Paper(content,"拍立得相纸",pos,new Vector2(310,246),Color.white);var image=Rect(mount,"实际照片",new Vector2(10,-10),new Vector2(290,163));image.gameObject.AddComponent<RawImage>().texture=photo.image;Label(mount,new Vector2(13,-184),new Vector2(284,36),15,photo.caption);Button(mount,new Vector2(220,-215),new Vector2(78,26),"删除",()=>s.photos.Delete(index));}}
 void FinalPage(Transform r){var s=GameSession.I;Heading(r,new Vector2(88,-167),new Vector2(330,65),29,"熟悉的清晨，\n多了一个约定。");Label(r,new Vector2(89,-261),new Vector2(309,216),20,"九尾喜欢安静，\n黑白咪喜欢小球，\n顶流毛毛喜欢吃完后有人陪。\n\n以后路过这里，\n记得和三位朋友打个招呼。");var mount=Paper(r,"最后一页合照",new Vector2(442,-156),new Vector2(619,372),Color.white);var pic=Rect(mount,"三猫真实合照",new Vector2(13,-13),new Vector2(593,333));pic.gameObject.AddComponent<RawImage>().texture=s.ending.PortraitPhoto;Small(mount,19,-347,"九尾 · 黑白咪 · 顶流毛毛   /   我们的校园合照");}
 void VolumeSlider(Transform r,Vector2 p){var root=Rect(r,"背景音乐音量",p,new Vector2(840,42));var slider=root.gameObject.AddComponent<Slider>();var track=Rect(root,"音量轨道",new Vector2(0,-17),new Vector2(840,7));track.gameObject.AddComponent<Image>().color=new Color(.75f,.77f,.68f);var fillArea=Rect(root,"填充范围",new Vector2(0,-17),new Vector2(840,7));var fill=Rect(fillArea,"音量填充",Vector2.zero,new Vector2(840,7));fill.gameObject.AddComponent<Image>().color=ink;var handleArea=Rect(root,"滑块范围",new Vector2(0,-5),new Vector2(840,32));var handle=Card(handleArea,"音量滑块",Vector2.zero,new Vector2(26,32),accent);handle.anchorMin=Vector2.zero;handle.anchorMax=Vector2.one;handle.sizeDelta=new Vector2(26,0);fill.anchorMin=Vector2.zero;fill.anchorMax=Vector2.one;fill.sizeDelta=Vector2.zero;slider.fillRect=fill;slider.handleRect=handle;slider.targetGraphic=handle.GetComponent<Image>();slider.minValue=0;slider.maxValue=1;slider.value=GameSession.I.volume;slider.onValueChanged.AddListener(v=>GameSession.I.SetVolume(v));}
 void OnDestroy(){if(paperMat)Destroy(paperMat);if(rounded){var tex=rounded.texture;Destroy(rounded);Destroy(tex);}}
}
